<?php
declare(strict_types=1);
namespace App\Actions\Admin\PublicRequests;
use App\Models\Admin\AdminUser; use App\Models\Admin\PublicRequests\ContactRequest; use App\Models\Admin\PublicRequests\TrialRequest; use Illuminate\Support\Facades\DB;
final class ProcessPublicRequestAction { public function reply(ContactRequest $request,string $reply,AdminUser $admin):ContactRequest{return DB::transaction(function()use($request,$reply,$admin){$request->update(['status'=>'replied','reply'=>$reply,'replied_by'=>$admin->id,'replied_at'=>now()]);return $request->refresh();});} public function approve(TrialRequest $request,AdminUser $admin):TrialRequest{return DB::transaction(function()use($request,$admin){abort_unless($request->status==='pending',409);$request->update(['status'=>'approved','processed_by'=>$admin->id,'processed_at'=>now()]);return $request->refresh();});} public function reject(TrialRequest $request,string $reason,AdminUser $admin):TrialRequest{return DB::transaction(function()use($request,$reason,$admin){abort_unless($request->status==='pending',409);$request->update(['status'=>'rejected','processed_by'=>$admin->id,'processed_at'=>now(),'rejection_reason'=>$reason]);return $request->refresh();});} }
